# Knowledge base: plain-English explanations and per-goal recommendations.
# Goals: power = Power saving, balanced = Balanced (stock), single = Single-core performance,
#        multi = Multi-core performance, latency = Low-latency gaming.
# A recommendation is an option label (matched against the setting's own options, case-insensitive prefix),
# or free text starting with '~' when it's advice rather than one exact option. '' = no opinion / leave as is.
# Each entry: (regex on the setting name, title, explanation, {goal: rec}, note)

G = ('power', 'balanced', 'single', 'multi', 'latency')
def R(power='', balanced='', single='', multi='', latency=''):
    return dict(power=power, balanced=balanced, single=single, multi=multi, latency=latency)

